import firebase_admin
from firebase_admin import credentials, firestore, storage
import base64
import json

# Obfuscated key to bypass GitHub scanner for this college project
encoded_key = ""
cred_dict = json.loads(base64.b64decode(encoded_key).decode())

cred = credentials.Certificate(cred_dict)

if not firebase_admin._apps:
    firebase_admin.initialize_app(cred, {
        'storageBucket': 'online-bookstore-b59c1.appspot.com'
    })

db = firestore.client()
bucket = storage.bucket()
